const state={page:'dashboard',leads:[],accounts:[],tasks:[],activeTask:null,rpaJob:null,rpaPollTimer:null,products:[],quotes:[],orders:[],shipments:[],conversations:[],activeConversation:null,knowledge:[],knowledgeRules:{prices:[],freight:[],aftersales:[]},knowledgeSummary:null,operations:{nodes:[],bindings:[],jobs:[],events:[]},inventory:{overview:{metrics:{},inventory:[],batches:[]},suppliers:[],warehouses:[],purchaseOrders:[],movements:[],adjustments:[]}};
const titles={dashboard:'经营总览',leads:'门店线索',wechat:'微信获客',operations:'执行设备与客户',conversations:'会话工作台',knowledge:'知识库中心',commerce:'商品与报价',inventory:'进销存中心',orders:'订单与发货',audit:'审计日志'};
const FRIEND_DAILY_CAP=150;
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
async function api(path,options={},retried=false){const token=sessionStorage.getItem('agent_admin_token')||'';const headers=new Headers(options.headers||{});if(token)headers.set('X-Admin-Token',token);const res=await fetch(path,{...options,headers});const data=await res.json().catch(()=>({}));if(res.status===401&&data.code==='admin_token_required'&&!retried){const value=window.prompt('请输入中央控制台管理口令');if(value){sessionStorage.setItem('agent_admin_token',value.trim());return api(path,options,true)}}if(!res.ok)throw new Error(data.error||'请求失败');return data}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function money(v){return '¥'+Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:0,maximumFractionDigits:2})}
function qty(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:4})}
function badge(text){let c='gray';if(['在线','已通过','添加成功','已付款','已发货','在售','履约中','启用','可售','已审批','已全部到货','已占库','已全部发货','已签收','已核销'].includes(text))c='';if(['待执行','待确认','待付款','报价中','已发送','申请已发送','暂停待处理','草稿','待质检','部分到货','待占库','未占库','部分发货','运输中','待审批'].includes(text))c='warn';if(['添加失败','停止联系','离线','异常','已关闭','拒收','物流异常','已取消'].includes(text))c='red';return `<span class="badge ${c}">${text||'-'}</span>`}
function escapeHtml(v=''){return String(v).replace(/[&<>'"]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[s]))}

$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;showPage(b.dataset.page)});
function showPage(page){state.page=page;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));$('#page-title').textContent=titles[page];refreshCurrent()}
async function refreshCurrent(){const loaders={dashboard:loadDashboard,leads:loadLeads,wechat:async()=>{await loadAccounts();await Promise.all([loadFriendTasks(),loadRpaJob()])},operations:loadOperations,conversations:loadConversations,knowledge:loadKnowledge,commerce:async()=>{await loadProducts();await loadQuotes()},inventory:loadInventory,orders:loadOrders,audit:loadAudit};try{await loaders[state.page]()}catch(e){toast(e.message)}}
setInterval(()=>{$('#clock').textContent=new Date().toLocaleString('zh-CN',{hour12:false})},1000);
setInterval(()=>{if(state.page==='operations')loadOperations(true)},5000);

async function loadDashboard(){const d=await api('/api/dashboard');const defs=[['◎','线索总量',d.metrics.leads],['◫','活跃会话',d.metrics.conversations],['▣','销售订单',d.metrics.orders],['¥','累计销售额',money(d.metrics.revenue)],['!','低库存商品',d.metrics.low_stock],['↘','待办采购单',d.metrics.pending_purchase],['↗','可发货订单',d.metrics.ready_to_ship],['⚠','物流异常',d.metrics.shipment_exceptions]];$('#metrics').innerHTML=defs.map(x=>`<div class="metric-card"><div class="metric-icon">${x[0]}</div><div class="metric-value">${x[2]}</div><div class="metric-label">${x[1]}</div></div>`).join('');const max=Math.max(1,...d.funnel.map(x=>x.value));$('#funnel').innerHTML=(d.funnel.length?d.funnel:[{name:'暂无线索',value:0}]).map(x=>`<div class="funnel-col"><div class="funnel-value">${x.value}</div><div class="funnel-bar" style="height:${Math.max(8,x.value/max*145)}px"></div><div class="funnel-label">${x.name}</div></div>`).join('');const actions=[['导入并校验门店线索',d.metrics.leads?'线索库已有数据，可继续补充':'导入 Excel 或 CSV 联系人文件'],['执行加好友队列',`${d.metrics.pending_tasks} 条任务等待处理`],['处理客户会话',`${d.metrics.conversations} 个会话已建立`],['补货与采购处理',`${d.metrics.low_stock} 项低库存，${d.metrics.pending_purchase} 张采购单待办`],['订单与发货处理',`${d.metrics.ready_to_ship} 张可发货，${d.metrics.shipment_exceptions} 张物流异常`]];$('#action-suggestions').innerHTML=actions.map((x,i)=>`<div class="suggestion"><span class="num">${i+1}</span><div><b>${x[0]}</b><small>${x[1]}</small></div></div>`).join('');$('#recent-activity').innerHTML=d.recent.length?d.recent.map(x=>`<div class="timeline-item"><b>${escapeHtml(x.action)}</b><p>${escapeHtml(x.detail||x.object_type)}</p><time>${x.created_at}</time></div>`).join(''):'<div class="empty-state"><p>暂无业务动态</p></div>'}

async function loadLeads(){const q=encodeURIComponent($('#lead-search')?.value||'');const status=encodeURIComponent($('#lead-status-filter')?.value||'');state.leads=await api(`/api/leads?q=${q}&status=${status}`);$('#lead-rows').innerHTML=state.leads.length?state.leads.map(l=>`<tr><td><input class="lead-check" type="checkbox" value="${l.id}"></td><td class="store-cell"><b>${escapeHtml(l.store_name)}</b><small>${escapeHtml(l.wechat_id||l.phone)}</small></td><td>${escapeHtml(l.contact_name||'-')}<br><small>${escapeHtml(l.phone)}</small></td><td>${escapeHtml(l.region||'-')}<br><small>${escapeHtml(l.store_type||'-')}</small></td><td>${escapeHtml(l.source||'-')}<br><small>${escapeHtml(l.source_basis||'-')}</small></td><td class="score">${l.score}</td><td>${badge(l.status)}</td><td>${escapeHtml(l.owner)}</td><td><button class="button ghost small" onclick="quickUpdateLead(${l.id})">推进</button></td></tr>`).join(''):'<tr><td colspan="9"><div class="empty-state"><h3>还没有门店线索</h3><p>导入 Excel 或 CSV 联系人文件开始</p></div></td></tr>'}
$('#lead-search').addEventListener('input',()=>{clearTimeout(window.leadTimer);window.leadTimer=setTimeout(loadLeads,250)});$('#lead-status-filter').addEventListener('change',loadLeads);$('#select-all-leads').addEventListener('change',e=>$$('.lead-check').forEach(x=>x.checked=e.target.checked));
$('#csv-file').addEventListener('change',async e=>{if(!e.target.files[0])return;const fd=new FormData();fd.append('file',e.target.files[0]);try{const d=await api('/api/leads/import',{method:'POST',body:fd});const n=$('#import-result');n.classList.remove('hidden');const sheetText=(d.sheets||[]).map(s=>`${s.name} ${s.rows}行`).join('，');n.textContent=`${d.filename} 导入完成：成功 ${d.imported} 条，重复 ${d.duplicate} 条，无效 ${d.invalid} 条；来源待核验 ${d.unverified_source||0} 条，可用于微信RPA ${d.rpa_ready} 条，仅作资料留存 ${d.reference_only} 条${sheetText?`；识别 ${sheetText}`:''}`;toast('联系人文件导入完成');await loadLeads()}catch(err){toast(err.message)}e.target.value=''})
async function quickUpdateLead(id){const lead=state.leads.find(x=>x.id===id);const stages=['待触达','已触达','已建立联系','需求确认','报价中','待成交','履约中','复购培育','停止联系'];const next=stages[(stages.indexOf(lead.status)+1)%stages.length];await api(`/api/leads/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:next})});toast(`已推进至：${next}`);loadLeads()}

async function loadAccounts(){state.accounts=await api('/api/wechat/accounts');$('#account-cards').innerHTML=state.accounts.map(a=>{const dailyCap=Math.max(1,Math.min(FRIEND_DAILY_CAP,a.daily_limit));const pct=Math.min(100,a.used_today/dailyCap*100);return `<div class="account-card"><div class="account-top"><div class="account-avatar">微</div>${badge(a.status)}</div><h3>${escapeHtml(a.nickname)}</h3><p>${escapeHtml(a.wechat_no)} · RPA授权通道</p><div class="quota"><div class="quota-row"><span>今日已执行</span><b>${a.used_today}/${dailyCap}</b></div><div class="progress"><i style="width:${pct}%"></i></div></div><p style="margin-top:12px">${escapeHtml(a.approval_ref||'腾讯RPA授权范围')}</p></div>`}).join('');const options=state.accounts.filter(a=>a.status==='在线').map(a=>`<option value="${a.id}">${escapeHtml(a.nickname)}（今日剩余 ${Math.max(0,Math.min(FRIEND_DAILY_CAP,a.daily_limit)-a.used_today)}）</option>`).join('');$('#task-account').innerHTML=options;$('#rpa-account').innerHTML=options}
function openAccountDialog(){$('#account-dialog').showModal()}
async function createAccount(e){e.preventDefault();await api('/api/wechat/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nickname:$('#account-nickname').value,wechat_no:$('#account-wechat').value,daily_limit:$('#account-limit').value,approval_ref:$('#account-approval').value})});$('#account-dialog').close();toast('微信账号已添加');loadAccounts()}
function openFriendTaskDialog(){const ids=$$('.lead-check:checked').map(x=>Number(x.value));if(!ids.length)return toast('请先选择门店线索');window.selectedLeadIds=ids;$('#selected-lead-count').textContent=`已选择 ${ids.length} 家门店`;loadAccounts().then(()=>$('#friend-task-dialog').showModal())}
async function createFriendTasks(e){e.preventDefault();const d=await api('/api/friend-tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lead_ids:window.selectedLeadIds,account_id:$('#task-account').value,greeting:$('#task-greeting').value,remark:$('#task-remark').value})});$('#friend-task-dialog').close();toast(`已创建 ${d.created} 条RPA任务，来源待核验 ${d.unverified_source||0} 条，跳过 ${d.skipped} 条，无可搜索手机号 ${d.unsearchable||0} 条`);showPage('wechat')}
async function loadFriendTasks(){state.tasks=await api('/api/friend-tasks');const pending=state.tasks.filter(t=>t.status==='待执行');if(!state.activeTask||!pending.some(t=>t.id===state.activeTask))state.activeTask=pending.length?pending[pending.length-1].id:null;renderManualWorkbench();$('#task-rows').innerHTML=state.tasks.length?state.tasks.map(t=>`<tr class="${t.id===state.activeTask?'task-focus':''}"><td>#${t.id}</td><td class="store-cell"><b>${escapeHtml(t.store_name)}</b><small>${escapeHtml(t.wechat_id||t.phone)}</small></td><td><b>${escapeHtml(t.region||'未填写地区')}</b></td><td>${escapeHtml(t.account_name)}<br><small>${escapeHtml(t.wechat_no)}</small></td><td title="${escapeHtml(t.greeting)}"><b>${escapeHtml(t.greeting.slice(0,22))}${t.greeting.length>22?'…':''}</b><br><small>备注：${escapeHtml(t.remark||'-')}</small></td><td>${badge(t.result_status||t.status)}</td><td>${t.executed_at||'-'}</td><td title="${escapeHtml(t.result_note||'')}">${escapeHtml((t.result_note||'-').slice(0,34))}${(t.result_note||'').length>34?'…':''}</td><td>${t.status==='待执行'?`<button class="button primary small" onclick="focusTask(${t.id})">单条执行</button>`:''}${t.status==='已发送'?`<button class="button secondary small" onclick="acceptTask(${t.id})">确认添加成功</button>`:''}</td></tr>`).join(''):'<tr><td colspan="9">暂无任务</td></tr>'}
function renderManualWorkbench(){const pending=state.tasks.filter(t=>t.status==='待执行');const completed=state.tasks.filter(t=>!['待执行','执行中'].includes(t.status)).length;$('#manual-progress').textContent=`待执行 ${pending.length} · 已回写 ${completed}`;const t=state.tasks.find(x=>x.id===state.activeTask);if(!t){$('#manual-workbench').innerHTML='<div class="manual-empty"><div><h3>当前没有待执行客户</h3><p>请先在“门店线索”中勾选客户并创建RPA队列。</p></div></div>';return}const target=t.wechat_id||t.phone;$('#manual-workbench').innerHTML=`<div class="manual-card"><section class="manual-person"><h3>${escapeHtml(t.store_name)}</h3><p>${escapeHtml(t.contact_name||'未填写联系人')} · ${escapeHtml(t.region||'未填写地区')}</p><div class="manual-field"><label>微信搜索值</label><div class="copy-row"><div class="copy-value">${escapeHtml(target)}</div><button class="button secondary" onclick="copyTaskField(${t.id},'target')">复制</button></div></div><div class="source-proof"><b>来源依据</b><br>${escapeHtml(t.source_basis||'未填写')}<br><small>${escapeHtml(t.source||'')}</small></div></section><section class="manual-greeting"><label>好友验证语</label><textarea id="active-greeting" readonly>${escapeHtml(t.greeting)}</textarea><div class="remark-preview"><b>微信备注</b>${escapeHtml(t.remark||t.store_name)}</div><div class="manual-actions"><button class="button secondary" onclick="copyTaskField(${t.id},'greeting')">复制验证语</button><button class="button primary" onclick="executeRpaTask(${t.id})">RPA执行当前客户</button><button class="button ghost" onclick="skipTask(${t.id})">跳过此客户</button></div><p class="dialog-note">点击RPA执行后，系统将搜索该账号、填写验证语与备注、提交一次申请并回写结果。</p></section></div>`}
function focusTask(id){state.activeTask=id;renderManualWorkbench();document.querySelector('.workbench-panel')?.scrollIntoView({behavior:'smooth',block:'start'});loadFriendTasks()}
async function copyText(value){try{await navigator.clipboard.writeText(value)}catch(_){const input=document.createElement('textarea');input.value=value;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove()}toast('已复制')}
function copyTaskField(id,field){const t=state.tasks.find(x=>x.id===id);if(!t)return;copyText(field==='target'?(t.wechat_id||t.phone):t.greeting)}
async function executeRpaTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;if(!window.confirm(`RPA将立即向 ${t.store_name}（${t.wechat_id||t.phone}）执行一次好友申请，并写入备注“${t.remark||t.store_name}”。是否继续？`))return;toast('RPA正在执行，请不要操作微信窗口');try{const d=await api(`/api/friend-tasks/${id}/rpa-execute`,{method:'POST'});toast(`RPA结果：${d.status}`)}catch(e){toast(e.message)}await Promise.all([loadFriendTasks(),loadAccounts(),loadRpaJob()])}
async function startRpaQueue(){const accountId=$('#rpa-account').value;if(!accountId)return toast('请选择执行账号');const pending=state.tasks.filter(t=>t.status==='待执行'&&String(t.account_id)===String(accountId)).length;if(!pending)return toast('该账号没有待执行任务');if(!window.confirm(`将启动RPA队列，按顺序处理 ${pending} 条待执行任务。是否继续？`))return;try{state.rpaJob=await api('/api/rpa/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account_id:accountId,interval_seconds:$('#rpa-interval').value})});renderRpaJob();scheduleRpaPoll();toast('RPA队列已启动')}catch(e){toast(e.message)}}
async function stopRpaQueue(){if(!state.rpaJob?.id)return;if(!window.confirm('队列会在当前任务结束后停止，是否继续？'))return;try{await api(`/api/rpa/jobs/${state.rpaJob.id}/stop`,{method:'POST'});toast('已发送停止指令');scheduleRpaPoll()}catch(e){toast(e.message)}}
async function loadRpaJob(){try{state.rpaJob=await api('/api/rpa/jobs/current');renderRpaJob();if(['等待启动','运行中'].includes(state.rpaJob.status))scheduleRpaPoll()}catch(e){toast(e.message)}}
function scheduleRpaPoll(){clearTimeout(state.rpaPollTimer);state.rpaPollTimer=setTimeout(async()=>{await Promise.all([loadRpaJob(),loadFriendTasks(),loadAccounts()])},1500)}
function renderRpaJob(){const j=state.rpaJob||{status:'未启动',total:0,processed:0,success:0,failed:0,current_task_id:null,stop_reason:''};const active=['等待启动','运行中'].includes(j.status);const pct=j.total?Math.min(100,j.processed/j.total*100):0;$('#rpa-job-status').textContent=j.status;$('#rpa-progress-text').textContent=`${j.processed||0} / ${j.total||0}`;$('#rpa-progress-bar').style.width=`${pct}%`;$('#rpa-success-count').textContent=j.success||0;$('#rpa-failed-count').textContent=j.failed||0;$('#rpa-current-task').textContent=j.current_task_id?`#${j.current_task_id}`:'-';$('#rpa-current-label').textContent=active?'队列正在处理':'队列状态';$('#rpa-start-button').disabled=active;$('#rpa-stop-button').disabled=!active;const reason=$('#rpa-stop-reason');if(j.stop_reason){reason.textContent=j.stop_reason;reason.classList.remove('hidden')}else reason.classList.add('hidden')}
async function confirmTaskSent(id){if(!window.confirm('请确认：你已经在微信客户端中手动发送了好友申请。'))return;await api(`/api/friend-tasks/${id}/confirm-sent`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});toast('已记录为手动发送');await Promise.all([loadFriendTasks(),loadAccounts()])}
async function skipTask(id){const reason=window.prompt('跳过原因（可选）：','暂不处理');if(reason===null)return;await api(`/api/friend-tasks/${id}/skip`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast('已跳过当前客户');loadFriendTasks()}
async function acceptTask(id){if(!window.confirm('确认该客户已在微信中通过好友申请？'))return;await api(`/api/friend-tasks/${id}/accept`,{method:'POST'});toast('已记录客户通过，并创建会话');loadFriendTasks()}

async function loadOperations(silent=false){
  try{const [overview,conversations]=await Promise.all([api('/api/operations/overview'),api('/api/conversations')]);state.operations=overview;state.conversations=conversations;renderOperations()}catch(e){if(!silent)toast(e.message)}
}
function renderOperations(){
  const o=state.operations;const online=o.nodes.filter(n=>n.status==='online').length;const capacity=o.nodes.reduce((s,n)=>s+Number(n.max_active_conversations||0),0);const queued=o.jobs.filter(j=>['queued','leased'].includes(j.status)).length;const failed=o.jobs.filter(j=>j.status==='failed').length;
  const defs=[['⌁','执行设备',o.nodes.length],['●','在线设备',online],['◫','会话管理容量',capacity],['✓','已纳管客户',o.bindings.filter(b=>b.enabled).length],['↗','排队任务',queued],['!','失败任务',failed]];
  $('#operations-metrics').innerHTML=defs.map(x=>`<div class="metric-card"><div class="metric-icon">${x[0]}</div><div class="metric-value">${x[2]}</div><div class="metric-label">${x[1]}</div></div>`).join('');
  $('#worker-node-cards').innerHTML=o.nodes.length?o.nodes.map(n=>{const used=Number(n.binding_count||0),max=Number(n.max_active_conversations||500),pct=Math.min(100,used/Math.max(1,max)*100);return `<div class="node-card ${n.status}"><div class="node-card-head"><div><b>${escapeHtml(n.display_name)}</b><small>${escapeHtml(n.machine_name||n.node_id)}</small></div>${badge(n.status==='online'?'在线':n.status==='degraded'?'异常':'离线')}</div><p>微信账号标识：${escapeHtml(n.account_ref)}</p><div class="quota-row"><span>已纳管客户</span><b>${used}/${max}</b></div><div class="progress"><i style="width:${pct}%"></i></div><div class="node-meta"><span>${n.dry_run?'配置检查':'真实运行'}</span><span>待发 ${n.pending_jobs||0}</span><span>失败 ${n.failed_jobs||0}</span></div>${n.last_error?`<div class="node-error">${escapeHtml(n.last_error)}</div>`:''}</div>`}).join(''):'<div class="panel empty-node"><b>还没有执行设备</b><span>在微信电脑运行 scripts\\start_worker.ps1，程序会自动生成设备身份并注册；本机部署无需填写配置文件。</span></div>';
  $('#binding-node').innerHTML=o.nodes.map(n=>`<option value="${escapeHtml(n.node_id)}">${escapeHtml(n.display_name)} · ${escapeHtml(n.account_ref)}（${n.binding_count||0}/${n.max_active_conversations}）</option>`).join('');
  $('#binding-node').disabled=!o.nodes.length;$('#binding-submit').disabled=!o.nodes.length||!state.conversations.length;
  $('#binding-conversation').innerHTML=state.conversations.map(c=>`<option value="${c.id}">${escapeHtml(c.store_name)} · 会话#${c.id}</option>`).join('');
  $('#binding-rows').innerHTML=o.bindings.length?o.bindings.map(b=>`<tr><td><b>${escapeHtml(b.store_name)}</b><br><small>${escapeHtml(b.contact_ref)}</small></td><td>${escapeHtml(b.display_name)}<br><small>${escapeHtml(b.account_ref)}</small></td><td>${b.human_takeover?badge('需人工接管'):badge(b.auto_reply?'自动回复':'只监听')}</td><td>${b.last_inbound_at||'-'}</td><td>${b.last_outbound_at||'-'}</td><td>${b.pending_jobs||0}</td><td class="error-cell">${escapeHtml(b.last_error||'-')}</td><td>${b.human_takeover?`<button class="button secondary small" onclick="setConversationTakeover(${b.conversation_id},false)">恢复自动处理</button> `:''}<button class="button ghost small" onclick="toggleBinding(${b.id},'auto_reply',${b.auto_reply?0:1})">${b.auto_reply?'暂停自动回复':'开启自动回复'}</button> <button class="button danger small" onclick="toggleBinding(${b.id},'enabled',${b.enabled?0:1})">${b.enabled?'停用':'启用'}</button></td></tr>`).join(''):'<tr><td colspan="8">暂无绑定会话</td></tr>';
  const statusNames={queued:'排队',leased:'执行中',succeeded:'成功',failed:'失败',cancelled:'已取消'};
  $('#message-job-rows').innerHTML=o.jobs.length?o.jobs.map(j=>`<tr><td>#${j.id}</td><td>${escapeHtml(j.contact_ref)}</td><td>${badge(statusNames[j.status]||j.status)}</td><td>${j.attempts}</td><td>${j.completed_at||j.created_at}</td><td class="error-cell">${escapeHtml(j.last_error||'-')}</td></tr>`).join(''):'<tr><td colspan="6">暂无消息任务</td></tr>';
  $('#worker-events').innerHTML=o.events.length?o.events.slice(0,30).map(e=>`<div class="worker-event ${escapeHtml(e.severity)}"><span></span><div><b>${escapeHtml(e.event_type)}</b><p>${escapeHtml(e.detail)}</p><time>${e.created_at}</time></div></div>`).join(''):'<div class="empty-state" style="height:220px"><p>暂无节点事件</p></div>';
}
async function createChatBinding(e){e.preventDefault();try{await api('/api/operations/bindings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({node_id:$('#binding-node').value,conversation_id:$('#binding-conversation').value,contact_ref:$('#binding-contact').value.trim(),auto_reply:$('#binding-auto-reply').checked})});$('#binding-contact').value='';toast('微信会话绑定完成');await loadOperations()}catch(err){toast(err.message)}}
async function toggleBinding(id,field,value){try{await api(`/api/operations/bindings/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({[field]:Boolean(value)})});await loadOperations()}catch(e){toast(e.message)}}
async function setConversationTakeover(id,enabled){try{await api(`/api/operations/conversations/${id}/takeover`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});toast(enabled?'已转人工接管':'已恢复自动处理');await loadOperations()}catch(e){toast(e.message)}}

async function loadConversations(){state.conversations=await api('/api/conversations');$('#conversation-items').innerHTML=state.conversations.length?state.conversations.map(c=>`<div class="conversation-item ${state.activeConversation===c.id?'active':''}" onclick="openConversation(${c.id})"><div class="conversation-item-top"><b>${escapeHtml(c.store_name)}</b><time>${c.updated_at.slice(5,16)}</time></div><p>${escapeHtml(c.last_message||'暂无消息')}</p><span class="badge gray">${c.intent}</span></div>`).join(''):'<div class="empty-state" style="height:300px"><p>好友通过后将在这里建立会话</p></div>';if(state.activeConversation&&!state.conversations.find(x=>x.id===state.activeConversation))state.activeConversation=null}
async function openConversation(id){state.activeConversation=id;const c=state.conversations.find(x=>x.id===id);$('#chat-empty').classList.add('hidden');$('#chat-active').classList.remove('hidden');$('#chat-name').textContent=c.store_name;$('#chat-meta').textContent=`${c.contact_name||'未填写联系人'} · ${c.region||'未填写地区'} · ${c.stage}`;$('#chat-badges').innerHTML=badge(c.intent)+' '+badge(c.sentiment)+(c.human_takeover?' '+badge('需人工接管'):'');await loadConversations();const msgs=await api(`/api/conversations/${id}/messages`);$('#message-list').innerHTML=msgs.map(m=>`<div class="message ${m.sender==='sales'?'sales':'customer'}"><div class="bubble">${escapeHtml(m.content)}<time>${m.created_at.slice(5,16)}</time></div></div>`).join('');$('#message-list').scrollTop=$('#message-list').scrollHeight}
async function sendChatMessage(){const input=$('#message-input');if(!input.value.trim())return;try{const d=await api(`/api/operations/conversations/${state.activeConversation}/queue-message`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:input.value.trim(),idempotency_key:`web:${state.activeConversation}:${Date.now()}`})});input.value='';$('#suggestion-box').classList.add('hidden');toast(`消息任务 #${d.job_id} 已排队，节点确认发送后才会写入会话`);await openConversation(state.activeConversation)}catch(e){toast(e.message)}}
$('#message-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChatMessage()}})
async function getSuggestion(){if(!state.activeConversation)return;const d=await api(`/api/conversations/${state.activeConversation}/suggest`,{method:'POST'});state.pendingSuggestion=d.suggestion;const box=$('#suggestion-box');box.classList.remove('hidden');box.innerHTML=`<b>回复建议 · ${d.risk}</b><div style="margin-top:6px">${escapeHtml(d.suggestion)}</div><div class="suggestion-actions"><button class="button secondary small" onclick="useSuggestion()">采用建议</button></div>`}
function useSuggestion(){if(!state.pendingSuggestion)return;$('#message-input').value=state.pendingSuggestion;$('#message-input').focus()}

async function loadKnowledge(){const [summary,rules,settings]=await Promise.all([api('/api/knowledge/summary'),api('/api/knowledge/rules'),api('/api/ai/settings')]);state.knowledgeSummary=summary;state.knowledgeRules=rules;renderKnowledgeSummary();renderKnowledgeRules();renderAiSettings(settings);syncKnowledgePriceOptions();await loadKnowledgeEntries()}
function renderKnowledgeSummary(){const s=state.knowledgeSummary;const defs=[['◇','已发布知识',s.entries],['¥','价格规则',s.price_rules],['↗','运费规则',s.freight_rules],['!','售后规则',s.aftersales_rules],['⚑','高风险边界',s.high_risk]];$('#knowledge-metrics').innerHTML=defs.map(x=>`<div class="metric-card"><div class="metric-icon">${x[0]}</div><div class="metric-value">${x[2]}</div><div class="metric-label">${x[1]}</div></div>`).join('');const select=$('#knowledge-category');const current=select.value;select.innerHTML='<option value="">全部分类</option>'+s.categories.map(x=>`<option value="${escapeHtml(x.name)}">${escapeHtml(x.name)}（${x.count}）</option>`).join('');select.value=current}
function renderKnowledgeRules(){const r=state.knowledgeRules;$('#aftersales-rule-list').innerHTML=r.aftersales.map(x=>`<div class="rule-item high"><b>${escapeHtml(x.issue)} · ${escapeHtml(x.condition_text)} → ${escapeHtml(x.resolution)}</b><p>${escapeHtml(x.boundary_note||'最终方案由人工确认')}</p></div>`).join('');$('#freight-rule-list').innerHTML=r.freight.map(x=>`<div class="rule-item"><b>${escapeHtml(x.region_group)} · ${escapeHtml(x.sale_mode)}</b><p>${money(x.price)} / ${x.sale_mode==='整箱'?'箱':'粒'}</p></div>`).join('')}
async function loadKnowledgeEntries(){const q=encodeURIComponent($('#knowledge-search')?.value||'');const category=encodeURIComponent($('#knowledge-category')?.value||'');state.knowledge=await api(`/api/knowledge/entries?q=${q}&category=${category}`);$('#knowledge-entry-list').innerHTML=state.knowledge.length?state.knowledge.map(x=>`<div class="knowledge-entry"><div class="knowledge-entry-top"><div><h3>${escapeHtml(x.title)}</h3><small>${escapeHtml(x.category)} · v${x.version}</small></div>${badge(x.status)}</div><p>${escapeHtml(x.content)}</p><div class="knowledge-tags"><span class="knowledge-tag ${x.risk_level==='高'?'high':''}">风险 ${escapeHtml(x.risk_level)}</span><span class="knowledge-tag">${escapeHtml(x.automation_level)}</span>${String(x.tags||'').split(',').filter(Boolean).slice(0,5).map(t=>`<span class="knowledge-tag">${escapeHtml(t)}</span>`).join('')}</div></div>`).join(''):'<div class="empty-state" style="height:180px"><p>没有匹配的已发布知识</p></div>'}
function renderAiSettings(s){$('#ai-base-url').value=s.base_url||'https://api.deepseek.com';$('#ai-model').value=s.model||'deepseek-v4-flash';$('#ai-api-key').placeholder=s.api_key_masked?`当前 ${s.api_key_masked}；留空不修改`:'输入后由Windows系统加密保存';$('#ai-status').textContent=s.status||'未配置';$('#ai-status').className=`badge ${s.status==='连接正常'?'':'gray'}`;$('#ai-test-result').textContent=s.last_test_result||'未配置API时，系统仍使用本地规则检索，不会编造答案。'}
async function saveAiSettings(){try{const d=await api('/api/ai/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_url:$('#ai-base-url').value,model:$('#ai-model').value,api_key:$('#ai-api-key').value})});$('#ai-api-key').value='';toast('AI配置已加密保存，等待连接测试');await loadKnowledge()}catch(e){toast(e.message)}}
async function testAiConnection(){const result=$('#ai-test-result');result.textContent='正在测试连接…';try{const d=await api('/api/ai/test',{method:'POST'});result.textContent=`${d.result}：${d.models.join('、')}`;toast('DeepSeek连接正常');await loadKnowledge()}catch(e){result.textContent=e.message;toast(e.message)}}
async function askKnowledge(){const question=$('#knowledge-question').value.trim();if(!question)return toast('请输入客户问题');const box=$('#knowledge-answer');box.classList.remove('empty-answer');box.textContent='正在检索已发布知识…';try{const d=await api('/api/knowledge/answer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,use_ai:$('#knowledge-use-ai').checked})});box.innerHTML=`<div class="answer-meta"><span class="badge gray">回答方式：${escapeHtml(d.mode)}</span> <span class="badge ${d.risk==='高'?'red':d.risk==='中'?'warn':''}">风险：${escapeHtml(d.risk)}</span> ${d.requires_human?'<span class="badge red">必须转人工</span>':'<span class="badge">无需转人工</span>'}</div><div>${escapeHtml(d.answer)}</div><div class="answer-sources">决策依据：${escapeHtml(d.decision_basis||'-')}<br>知识来源：${d.sources.length?d.sources.map(escapeHtml).join('、'):'未检索到可靠知识'}</div>`}catch(e){box.textContent=e.message}}
function selectValues(id,values){const el=$(id);const current=el.value;el.innerHTML=values.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v||'无')}</option>`).join('');if(values.includes(current))el.value=current}
function syncKnowledgePriceOptions(){const prices=state.knowledgeRules.prices||[];const mode=$('#kb-sale-mode')?.value||'单粒';let rows=prices.filter(x=>x.sale_mode===mode);const products=[...new Set(rows.map(x=>x.product))];selectValues('#kb-product',products);const product=$('#kb-product').value;rows=rows.filter(x=>x.product===product);const grades=[...new Set(rows.map(x=>x.grade))];selectValues('#kb-grade',grades);const grade=$('#kb-grade').value;rows=rows.filter(x=>x.grade===grade);selectValues('#kb-spec',[...new Set(rows.map(x=>x.spec))])}
async function calculateKnowledgePrice(){try{const d=await api('/api/knowledge/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sale_mode:$('#kb-sale-mode').value,product:$('#kb-product').value,grade:$('#kb-grade').value,spec:$('#kb-spec').value,region_group:$('#kb-region').value,quantity:$('#kb-quantity').value})});const box=$('#kb-price-result');box.classList.remove('hidden');box.innerHTML=`<div><b>${escapeHtml(d.product)} ${escapeHtml(d.grade)} · ${escapeHtml(d.spec)} × ${d.quantity}</b><small>商品 ${money(d.goods_total)} + 运费 ${money(d.freight_total)}（${escapeHtml(d.region_group)}）</small></div><div><strong>${money(d.total)}</strong><small>${escapeHtml(d.boundary)}</small></div>`}catch(e){toast(e.message)}}
function openKnowledgeDialog(){$('#knowledge-dialog').showModal()}
async function createKnowledgeEntry(e){e.preventDefault();try{const d=await api('/api/knowledge/entries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('#knowledge-title').value,category:$('#knowledge-new-category').value,content:$('#knowledge-content').value,status:$('#knowledge-new-status').value})});$('#knowledge-dialog').close();$('#knowledge-title').value='';$('#knowledge-content').value='';toast(`知识已保存：${d.labels.category} / 风险${d.labels.risk_level}`);await loadKnowledge()}catch(err){toast(err.message)}}

async function loadInventory(){
  const [overview,suppliers,warehouses,purchaseOrders,movements,adjustments,products]=await Promise.all([api('/api/inventory/overview'),api('/api/inventory/suppliers'),api('/api/inventory/warehouses'),api('/api/inventory/purchase-orders'),api('/api/inventory/movements?limit=200'),api('/api/inventory/adjustments'),api('/api/products')]);
  state.inventory={overview,suppliers,warehouses,purchaseOrders,movements,adjustments};state.products=products;renderInventory();
}
function renderInventory(){
  const i=state.inventory,o=i.overview,m=o.metrics||{};const defs=[['□','可用库存',qty(m.available)],['▣','销售占用',qty(m.reserved)],['◈','待质检',qty(m.quarantine)],['↘','采购在途',qty(m.incoming)],['¥','可售库存成本',money(m.stock_value)],['!','低库存项',m.low_stock||0],['⌛','临期批次',m.expiring_batches||0]];
  $('#inventory-metrics').innerHTML=defs.map(x=>`<div class="metric-card"><div class="metric-icon">${x[0]}</div><div class="metric-value">${x[2]}</div><div class="metric-label">${x[1]}</div></div>`).join('');
  $('#inventory-rows').innerHTML=o.inventory.length?o.inventory.map(r=>{const low=Number(r.available_qty)<Number(r.reorder_point);return `<tr><td><b>${escapeHtml(r.name)}</b><br><small>${escapeHtml(r.sku)} · ${escapeHtml(r.unit)}</small></td><td>${escapeHtml(r.warehouse_name)}</td><td>${qty(r.sellable_on_hand)}</td><td>${qty(r.reserved_qty)}</td><td><b>${qty(r.available_qty)}</b></td><td>${qty(r.quarantine_qty)}</td><td>${qty(r.incoming_qty)}</td><td>${qty(r.reorder_point)}</td><td>${low?'<span class="badge red">需要补货</span>':'<span class="badge">正常</span>'}</td></tr>`}).join(''):'<tr><td colspan="9">暂无库存资料</td></tr>';
  $('#purchase-order-rows').innerHTML=i.purchaseOrders.length?i.purchaseOrders.map(p=>`<tr><td><b>${escapeHtml(p.po_no)}</b><br><small>${p.created_at}</small></td><td>${escapeHtml(p.supplier_name)}</td><td>${escapeHtml(p.warehouse_name)}</td><td>${escapeHtml(p.item_summary)}</td><td>${qty(p.ordered_qty)} / ${qty(p.received_qty)}</td><td>${money(p.total_amount)}</td><td>${p.expected_at||'-'}</td><td>${badge(p.status)}</td><td>${p.status==='草稿'?`<button class="button primary small" onclick="approvePurchaseOrder(${p.id})">审批</button>`:''}${['已审批','部分到货'].includes(p.status)?`<button class="button secondary small" onclick="openPurchaseReceiveDialog(${p.id})">登记到货</button>`:''}</td></tr>`).join(''):'<tr><td colspan="9">暂无采购单</td></tr>';
  $('#inventory-batch-rows').innerHTML=o.batches.length?o.batches.map(b=>`<tr><td><b>${escapeHtml(b.batch_no)}</b><br><small>${escapeHtml(b.supplier_name||'-')}</small></td><td>${escapeHtml(b.product_name)}<br><small>${escapeHtml(b.sku)}</small></td><td>${escapeHtml(b.warehouse_name)}</td><td>${qty(b.on_hand)} / ${qty(b.reserved_qty)}</td><td>${b.production_date||'-'}<br><small>${b.expiry_date||'未设置'}</small></td><td>${badge(b.quality_status)}</td><td>${b.quality_status==='待质检'?`<button class="button primary small" onclick="setBatchQuality(${b.id},'可售')">质检放行</button> <button class="button danger small" onclick="setBatchQuality(${b.id},'拒收')">拒收</button>`:'-'}</td></tr>`).join(''):'<tr><td colspan="7">暂无批次</td></tr>';
  $('#supply-master-data').innerHTML=`<div class="master-group"><h3>供应商</h3>${i.suppliers.map(s=>`<div><b>${escapeHtml(s.name)}</b><span>${escapeHtml(s.code)} · ${escapeHtml(s.contact_name||'未填联系人')} · ${escapeHtml(s.payment_terms)}</span>${badge(s.status)}</div>`).join('')}</div><div class="master-group"><h3>仓库</h3>${i.warehouses.map(w=>`<div><b>${escapeHtml(w.name)}</b><span>${escapeHtml(w.code)} · ${escapeHtml(w.location||'未填地址')}</span>${w.is_default?'<span class="tag">默认</span>':badge(w.status)}</div>`).join('')}</div>`;
  $('#inventory-movement-rows').innerHTML=i.movements.length?i.movements.map(m=>`<tr><td>${m.created_at}</td><td><b>${escapeHtml(m.product_name)}</b><br><small>${escapeHtml(m.batch_no||'-')}</small></td><td>${escapeHtml(m.warehouse_name)}</td><td>${badge(m.movement_type)}</td><td class="movement-qty ${Number(m.quantity)>=0?'in':'out'}">${Number(m.quantity)>=0?'+':''}${qty(m.quantity)} ${escapeHtml(m.unit)}</td><td>${escapeHtml(m.reference_type)} #${escapeHtml(m.reference_id)}<br><small>${escapeHtml(m.note||'')}</small></td></tr>`).join(''):'<tr><td colspan="6">暂无库存流水</td></tr>';
  $('#inventory-adjustment-rows').innerHTML=i.adjustments.length?i.adjustments.map(a=>`<tr><td><b>${escapeHtml(a.adjustment_no)}</b><br><small>${a.created_at}</small></td><td>${escapeHtml(a.product_name)}<br><small>${escapeHtml(a.batch_no||'新批次')}</small></td><td class="movement-qty ${Number(a.quantity_delta)>=0?'in':'out'}">${Number(a.quantity_delta)>0?'+':''}${qty(a.quantity_delta)}</td><td>${escapeHtml(a.reason)}</td><td>${badge(a.status)}</td><td>${a.status==='待审批'?`<button class="button primary small" onclick="approveInventoryAdjustment(${a.id})">审批过账</button>`:'-'}</td></tr>`).join(''):'<tr><td colspan="6">暂无盘点调整</td></tr>';
}
function openSupplierDialog(){$('#supplier-dialog').showModal()}
async function createSupplier(e){e.preventDefault();try{await api('/api/inventory/suppliers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#supplier-name').value,code:$('#supplier-code').value,contact_name:$('#supplier-contact').value,phone:$('#supplier-phone').value,payment_terms:$('#supplier-payment-terms').value,lead_time_days:$('#supplier-lead-days').value,notes:$('#supplier-notes').value})});$('#supplier-dialog').close();e.target.reset();toast('供应商已建立');await loadInventory()}catch(err){toast(err.message)}}
function openWarehouseDialog(){$('#warehouse-dialog').showModal()}
async function createWarehouse(e){e.preventDefault();try{await api('/api/inventory/warehouses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#warehouse-name').value,code:$('#warehouse-code').value,location:$('#warehouse-location').value})});$('#warehouse-dialog').close();e.target.reset();toast('仓库已建立');await loadInventory()}catch(err){toast(err.message)}}
async function openPurchaseOrderDialog(){if(!state.inventory.suppliers.length)await loadInventory();$('#po-supplier').innerHTML=state.inventory.suppliers.filter(s=>s.status==='启用').map(s=>`<option value="${s.id}">${escapeHtml(s.name)} · ${escapeHtml(s.code)}</option>`).join('');$('#po-warehouse').innerHTML=state.inventory.warehouses.filter(w=>w.status==='启用').map(w=>`<option value="${w.id}">${escapeHtml(w.name)}</option>`).join('');$('#po-product').innerHTML=state.products.map(p=>`<option value="${p.id}" data-cost="${p.price}">${escapeHtml(p.name)} · ${escapeHtml(p.unit)}</option>`).join('');if(state.products.length)$('#po-unit-cost').value=state.products[0].price;const d=new Date();d.setDate(d.getDate()+3);$('#po-expected-at').value=d.toISOString().slice(0,10);$('#purchase-order-dialog').showModal()}
$('#po-product').addEventListener('change',e=>{$('#po-unit-cost').value=e.target.selectedOptions[0]?.dataset.cost||''})
async function createPurchaseOrder(e){e.preventDefault();try{const d=await api('/api/inventory/purchase-orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplier_id:$('#po-supplier').value,warehouse_id:$('#po-warehouse').value,expected_at:$('#po-expected-at').value,notes:$('#po-notes').value,items:[{product_id:$('#po-product').value,quantity:$('#po-quantity').value,unit_cost:$('#po-unit-cost').value}]})});$('#purchase-order-dialog').close();toast(`采购单 ${d.po_no} 已建立，等待审批`);await loadInventory()}catch(err){toast(err.message)}}
async function approvePurchaseOrder(id){if(!window.confirm('审批后该采购单可以办理到货入库，是否确认？'))return;try{await api(`/api/inventory/purchase-orders/${id}/approve`,{method:'POST'});toast('采购单已审批');await loadInventory()}catch(e){toast(e.message)}}
async function openPurchaseReceiveDialog(id){try{const items=await api(`/api/inventory/purchase-orders/${id}/items`);const pending=items.filter(x=>Number(x.ordered_qty)>Number(x.received_qty));if(!pending.length)return toast('该采购单已经全部到货');$('#receive-po-id').value=id;$('#receive-item').innerHTML=pending.map(x=>`<option value="${x.id}" data-remaining="${Number(x.ordered_qty)-Number(x.received_qty)}">${escapeHtml(x.product_name)} · 剩余 ${qty(Number(x.ordered_qty)-Number(x.received_qty))}${escapeHtml(x.unit)}</option>`).join('');syncReceiveRemaining();const po=state.inventory.purchaseOrders.find(x=>x.id===id);$('#purchase-receive-info').textContent=`${po?.po_no||'#'+id} · ${po?.supplier_name||''}`;$('#receive-batch-no').value='BAT'+new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);$('#purchase-receive-dialog').showModal()}catch(e){toast(e.message)}}
function syncReceiveRemaining(){const option=$('#receive-item').selectedOptions[0];if(!option)return;$('#receive-quantity').value=option.dataset.remaining;$('#receive-quantity').max=option.dataset.remaining}
$('#receive-item').addEventListener('change',syncReceiveRemaining)
async function receivePurchaseOrder(e){e.preventDefault();try{const id=$('#receive-po-id').value;const d=await api(`/api/inventory/purchase-orders/${id}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_id:$('#receive-item').value,quantity:$('#receive-quantity').value,batch_no:$('#receive-batch-no').value,production_date:$('#receive-production-date').value,expiry_date:$('#receive-expiry-date').value})});$('#purchase-receive-dialog').close();toast(`批次 ${d.batch_no} 已进入待质检区，采购单状态：${d.purchase_status}`);await loadInventory()}catch(err){toast(err.message)}}
async function setBatchQuality(id,status){if(!window.confirm(`确认将该批次质检状态更新为“${status}”？`))return;try{await api(`/api/inventory/batches/${id}/quality`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({quality_status:status,note:`操作员确认：${status}`})});toast(`批次已更新为${status}`);await loadInventory();if(state.page==='commerce')loadProducts()}catch(e){toast(e.message)}}
function openAdjustmentDialog(){$('#adjustment-product').innerHTML=state.products.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${escapeHtml(p.sku)}</option>`).join('');$('#adjustment-warehouse').innerHTML=state.inventory.warehouses.filter(w=>w.status==='启用').map(w=>`<option value="${w.id}">${escapeHtml(w.name)}</option>`).join('');syncAdjustmentBatches();$('#adjustment-dialog').showModal()}
function syncAdjustmentBatches(){const product=$('#adjustment-product')?.value,warehouse=$('#adjustment-warehouse')?.value;const rows=(state.inventory.overview.batches||[]).filter(b=>String(b.product_id)===String(product)&&String(b.warehouse_id)===String(warehouse)&&Number(b.on_hand)>0);$('#adjustment-batch').innerHTML='<option value="">盘盈新增批次（仅正数）</option>'+rows.map(b=>`<option value="${b.id}">${escapeHtml(b.batch_no)} · 现存${qty(b.on_hand)} · ${escapeHtml(b.quality_status)}</option>`).join('')}
async function createInventoryAdjustment(e){e.preventDefault();try{const d=await api('/api/inventory/adjustments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:$('#adjustment-product').value,warehouse_id:$('#adjustment-warehouse').value,batch_id:$('#adjustment-batch').value,quantity_delta:$('#adjustment-quantity').value,reason:$('#adjustment-reason').value})});$('#adjustment-dialog').close();toast(`调整单 ${d.adjustment_no} 已提交，等待审批`);await loadInventory()}catch(err){toast(err.message)}}
async function approveInventoryAdjustment(id){if(!window.confirm('审批会立即产生不可变库存流水，是否确认账实差异已经复核？'))return;try{await api(`/api/inventory/adjustments/${id}/approve`,{method:'POST'});toast('库存调整已审批过账');await loadInventory()}catch(e){toast(e.message)}}

async function loadProducts(){state.products=await api('/api/products');$('#product-cards').innerHTML=state.products.map(p=>`<div class="product-card"><div class="product-top"><span class="tag">${escapeHtml(p.grade)}</span>${badge(p.status)}</div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.origin)} · SKU ${escapeHtml(p.sku)}</p><div class="product-price">${money(p.price)}<small> / ${p.unit}</small></div><div class="stock">可售库存：${p.stock} ${p.unit}</div></div>`).join('');$('#quote-product').innerHTML=state.products.map(p=>`<option value="${p.id}" data-price="${p.price}">${escapeHtml(p.name)} · ${money(p.price)}/${p.unit}</option>`).join('');if(state.products.length)$('#quote-price').value=state.products[0].price}
$('#quote-product').addEventListener('change',e=>{$('#quote-price').value=e.target.selectedOptions[0].dataset.price})
async function loadQuotes(){state.quotes=await api('/api/quotes');$('#quote-rows').innerHTML=state.quotes.length?state.quotes.map(q=>`<tr><td>#${q.id}</td><td>${escapeHtml(q.store_name)}</td><td>${escapeHtml(q.product_name)}</td><td>${q.quantity}${q.unit}</td><td>${money(q.unit_price)}</td><td>${money(q.freight)}</td><td><b>${money(q.total)}</b></td><td>${q.valid_until}</td><td>${badge(q.status)}</td><td>${q.status==='待确认'?`<button class="button primary small" onclick="openOrderDialog(${q.id})">转订单</button>`:''}</td></tr>`).join(''):'<tr><td colspan="10">暂无报价</td></tr>'}
async function openQuoteDialog(){await Promise.all([loadProducts(),loadLeads()]);$('#quote-lead').innerHTML=state.leads.filter(l=>!l.stop_marketing).map(l=>`<option value="${l.id}">${escapeHtml(l.store_name)} · ${escapeHtml(l.region)}</option>`).join('');$('#quote-dialog').showModal()}
async function createQuote(e){e.preventDefault();const d=await api('/api/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lead_id:$('#quote-lead').value,product_id:$('#quote-product').value,quantity:$('#quote-quantity').value,unit_price:$('#quote-price').value,freight:$('#quote-freight').value,valid_days:$('#quote-valid-days').value})});$('#quote-dialog').close();toast(`报价已创建，总额 ${money(d.total)}`);loadQuotes()}
function openOrderDialog(id){const q=state.quotes.find(x=>x.id===id);$('#order-quote-id').value=id;$('#order-quote-info').textContent=`${q.store_name} · ${q.product_name} · ${money(q.total)}`;const lead=state.leads.find(x=>x.id===q.lead_id);if(lead){$('#order-receiver').value=lead.contact_name||'';$('#order-phone').value=lead.phone||''}$('#order-dialog').showModal()}
async function createOrder(e){e.preventDefault();const d=await api('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quote_id:$('#order-quote-id').value,receiver:$('#order-receiver').value,phone:$('#order-phone').value,address:$('#order-address').value,payment_status:$('#order-payment').value})});$('#order-dialog').close();toast(`订单 ${d.order_no} 已创建`);showPage('orders')}

async function loadOrders(){const [orders,shipments]=await Promise.all([api('/api/orders'),api('/api/inventory/shipments')]);state.orders=orders;state.shipments=shipments;renderOrders()}
function renderOrders(){const unpaid=state.orders.filter(o=>o.payment_status!=='已付款').length,pendingReserve=state.orders.filter(o=>!['已占库','已核销','部分核销'].includes(o.inventory_status)).length,ready=state.orders.filter(o=>o.payment_status==='已付款'&&Number(o.reserved_quantity)>0).length,partial=state.orders.filter(o=>o.fulfillment_status==='部分发货').length,exceptions=state.shipments.filter(s=>s.status==='物流异常').length;const defs=[['▣','销售订单',state.orders.length],['¥','待收款',unpaid],['□','待占库',pendingReserve],['↗','可发货',ready],['◫','部分发货',partial],['✓','发货单',state.shipments.length],['!','物流异常',exceptions]];$('#fulfillment-metrics').innerHTML=defs.map(x=>`<div class="metric-card"><div class="metric-icon">${x[0]}</div><div class="metric-value">${x[2]}</div><div class="metric-label">${x[1]}</div></div>`).join('');$('#order-rows').innerHTML=state.orders.length?state.orders.map(o=>{const outstanding=Math.max(0,Number(o.ordered_quantity)-Number(o.fulfilled_quantity));return `<tr><td><b>${escapeHtml(o.order_no)}</b><br><small>${escapeHtml(o.item_summary||'无商品明细')}</small></td><td>${escapeHtml(o.store_name)}</td><td><b>${money(o.amount)}</b><br>${badge(o.payment_status)}${o.payment_status==='待付款'?` <button class="button ghost small" onclick="markPaid(${o.id})">确认收款</button>`:''}</td><td>${badge(o.inventory_status)}<br><small>已占 ${qty(o.reserved_quantity)} / 待发 ${qty(outstanding)}</small></td><td>${badge(o.fulfillment_status)}<br><small>已发 ${qty(o.fulfilled_quantity)} / ${qty(o.ordered_quantity)}</small></td><td>${escapeHtml(o.receiver||'-')}<br><small>${escapeHtml(o.phone||'')} ${escapeHtml(o.address||'')}</small></td><td>${o.tracking_no?`${escapeHtml(o.carrier)}<br><small>${escapeHtml(o.tracking_no)} · ${escapeHtml(o.shipment_status)} · 共${o.shipment_count}单</small>`:'-'}</td><td>${outstanding>0&&Number(o.reserved_quantity)<outstanding?`<button class="button secondary small" onclick="reserveOrder(${o.id})">占用库存</button> `:''}${Number(o.reserved_quantity)>0&&Number(o.fulfilled_quantity)===0?`<button class="button ghost small" onclick="releaseOrderStock(${o.id})">释放占库</button> `:''}${o.payment_status==='已付款'&&Number(o.reserved_quantity)>0?`<button class="button primary small" onclick="openShipmentDialog(${o.id})">发货</button>`:''}</td></tr>`}).join(''):'<tr><td colspan="8"><div class="empty-state"><h3>暂无订单</h3><p>在商品与报价页面将报价转为订单</p></div></td></tr>';$('#shipment-rows').innerHTML=state.shipments.length?state.shipments.map(s=>`<tr><td><b>${escapeHtml(s.shipment_no)}</b></td><td>${escapeHtml(s.order_no)}<br><small>${escapeHtml(s.store_name)}</small></td><td>${escapeHtml(s.warehouse_name)}</td><td>${qty(s.shipped_quantity)}</td><td>${escapeHtml(s.carrier)}<br><small>${escapeHtml(s.tracking_no)}</small></td><td>${badge(s.status)}</td><td>${s.shipped_at}</td><td>${s.status==='已发出'?`<button class="button secondary small" onclick="updateShipmentStatus(${s.id},'运输中')">运输中</button> `:''}${['已发出','运输中'].includes(s.status)?`<button class="button primary small" onclick="updateShipmentStatus(${s.id},'已签收')">已签收</button> <button class="button danger small" onclick="updateShipmentStatus(${s.id},'物流异常')">异常</button>`:'-'}</td></tr>`).join(''):'<tr><td colspan="8">暂无发货单</td></tr>'}
async function markPaid(id){await api(`/api/orders/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_status:'已付款'})});toast('收款状态已更新');loadOrders()}
async function reserveOrder(id){try{const d=await api(`/api/inventory/orders/${id}/reserve`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(`订单已占用库存 ${qty(d.reserved)}`);await Promise.all([loadOrders(),state.page==='inventory'?loadInventory():Promise.resolve()])}catch(e){toast(e.message)}}
async function releaseOrderStock(id){if(!window.confirm('确认释放该订单尚未核销的库存占用？'))return;try{await api(`/api/inventory/orders/${id}/release`,{method:'POST'});toast('销售占库已释放');await loadOrders()}catch(e){toast(e.message)}}
function openShipmentDialog(id){const o=state.orders.find(x=>x.id===id);if(!o||o.payment_status!=='已付款'||Number(o.reserved_quantity)<=0)return toast('订单必须已收款且已占库才能发货');$('#shipment-order-id').value=id;$('#shipment-order-info').textContent=`${o.order_no} · ${o.store_name} · 可发${qty(o.reserved_quantity)}`;$('#shipment-quantity').value=o.reserved_quantity;$('#shipment-quantity').max=o.reserved_quantity;$('#shipment-tracking').value='SF'+Date.now().toString().slice(-10);$('#shipment-dialog').showModal()}
async function createShipment(e){e.preventDefault();if(!window.confirm('确认后会立即按批次扣减库存并生成发货流水，是否继续？'))return;try{const d=await api('/api/inventory/shipments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_id:$('#shipment-order-id').value,carrier:$('#shipment-carrier').value,tracking_no:$('#shipment-tracking').value,quantity:$('#shipment-quantity').value,freight_cost:$('#shipment-cost').value})});$('#shipment-dialog').close();toast(`发货单 ${d.shipment_no} 已生成，库存已扣减`);await loadOrders()}catch(err){toast(err.message)}}
async function updateShipmentStatus(id,status){if(status==='物流异常'&&!window.confirm('确认将该运单标记为物流异常？'))return;try{await api(`/api/inventory/shipments/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,exception_note:status==='物流异常'?'操作员标记，等待核查':''})});toast(`物流状态已更新为${status}`);await loadOrders()}catch(e){toast(e.message)}}

async function loadAudit(){const rows=await api('/api/audit-logs');$('#audit-rows').innerHTML=rows.map(x=>`<tr><td>${x.created_at}</td><td><b>${escapeHtml(x.action)}</b></td><td>${escapeHtml(x.object_type)}</td><td>${escapeHtml(x.object_id)}</td><td>${escapeHtml(x.detail)}</td></tr>`).join('')}

window.refreshCurrent=refreshCurrent;window.openFriendTaskDialog=openFriendTaskDialog;window.createFriendTasks=createFriendTasks;window.quickUpdateLead=quickUpdateLead;window.openAccountDialog=openAccountDialog;window.createAccount=createAccount;window.loadFriendTasks=loadFriendTasks;window.focusTask=focusTask;window.copyTaskField=copyTaskField;window.executeRpaTask=executeRpaTask;window.startRpaQueue=startRpaQueue;window.stopRpaQueue=stopRpaQueue;window.confirmTaskSent=confirmTaskSent;window.skipTask=skipTask;window.acceptTask=acceptTask;window.loadOperations=loadOperations;window.createChatBinding=createChatBinding;window.toggleBinding=toggleBinding;window.setConversationTakeover=setConversationTakeover;window.loadConversations=loadConversations;window.openConversation=openConversation;window.sendChatMessage=sendChatMessage;window.getSuggestion=getSuggestion;window.useSuggestion=useSuggestion;window.loadKnowledge=loadKnowledge;window.loadKnowledgeEntries=loadKnowledgeEntries;window.saveAiSettings=saveAiSettings;window.testAiConnection=testAiConnection;window.askKnowledge=askKnowledge;window.syncKnowledgePriceOptions=syncKnowledgePriceOptions;window.calculateKnowledgePrice=calculateKnowledgePrice;window.openKnowledgeDialog=openKnowledgeDialog;window.createKnowledgeEntry=createKnowledgeEntry;window.openQuoteDialog=openQuoteDialog;window.createQuote=createQuote;window.openOrderDialog=openOrderDialog;window.createOrder=createOrder;window.markPaid=markPaid;window.openShipmentDialog=openShipmentDialog;window.createShipment=createShipment;window.loadAudit=loadAudit;
Object.assign(window,{loadInventory,openSupplierDialog,createSupplier,openWarehouseDialog,createWarehouse,openPurchaseOrderDialog,createPurchaseOrder,approvePurchaseOrder,openPurchaseReceiveDialog,receivePurchaseOrder,setBatchQuality,openAdjustmentDialog,syncAdjustmentBatches,createInventoryAdjustment,approveInventoryAdjustment,reserveOrder,releaseOrderStock,updateShipmentStatus});
loadDashboard();
